<?php use VO\Support\Template; ob_start(); ?>
<h1>Pedidos</h1><form method="get" action="/admin/pedidos" class="card"><label>Estado <select name="status"><option value="">Todos</option><?php foreach (['pending'=>'Pendiente','accepted'=>'Aceptado','in_progress'=>'En preparación','ready'=>'Listo','completed'=>'Completado','rejected'=>'Rechazado','cancelled'=>'Cancelado','expired'=>'Vencido'] as $k=>$v): ?><option value="<?= Template::e($k) ?>"<?= $status===$k?' selected':'' ?>><?= Template::e($v) ?></option><?php endforeach; ?></select></label><button class="btn">Filtrar</button></form>
<section class="card"><?php foreach ($orders as $o): ?><p><a href="/admin/pedidos/<?= (int)$o['id'] ?>"><?= Template::e($o['number']) ?></a> <strong><?= Template::e(['pending'=>'Pendiente','accepted'=>'Aceptado','in_progress'=>'En preparación','ready'=>'Listo','completed'=>'Completado','rejected'=>'Rechazado','cancelled'=>'Cancelado','expired'=>'Vencido'][$o['status']] ?? $o['status']) ?></strong> · <?= Template::e($o['branch_name']) ?> · $ <?= number_format(((int)$o['grand_total_cents'])/100,2,',','.') ?> · <?= Template::e($o['created_at']) ?></p><?php endforeach; if (!$orders): ?><p>No hay pedidos para mostrar.</p><?php endif; ?></section>
<?php $content = ob_get_clean(); $title = 'Pedidos'; require __DIR__ . '/layout.php'; ?>
